/* ===== Non-login landing restructure: tone and components preserved ===== */
.why-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:18px}
.why-card{background:#fff;border:1px solid var(--line);border-radius:28px;box-shadow:var(--shadow);padding:30px;border-left:6px solid var(--blue)}
.why-card:nth-child(2){border-left-color:var(--orange)}
.why-card:nth-child(3){border-left-color:var(--green)}
.why-card h3{color:var(--navy);font-size:22px;font-weight:900;letter-spacing:-.4px;margin-bottom:10px}
.why-card p{color:var(--muted);font-size:14px;line-height:1.75;font-weight:800}
.ai-recommendation-layout{display:grid;grid-template-columns:.9fr 1.1fr;gap:24px;align-items:stretch}
.ai-pop-card{background:#fff;border:3px solid var(--blue);border-radius:34px;box-shadow:var(--shadow-deep);padding:42px}
.ai-pop-card h3{font-size:34px;line-height:1.25;color:var(--navy);letter-spacing:-1px;font-weight:900;margin:16px 0 12px}
.ai-pop-card p{color:var(--muted);font-size:15px;line-height:1.8;font-weight:700}
.next-step-card{background:var(--navy);color:#fff;border-radius:34px;box-shadow:var(--shadow-deep);padding:42px;display:flex;flex-direction:column;justify-content:space-between}
.next-step-card h3{color:#fff;font-size:30px;line-height:1.28;letter-spacing:-.8px;font-weight:900;margin-bottom:14px}
.next-step-card p{color:#C9D8EA;font-size:15px;line-height:1.8;font-weight:700}
.final-cta{background:var(--navy);color:#fff;text-align:center;border-radius:36px;padding:56px 32px;box-shadow:var(--shadow-deep)}
.final-cta h2{color:#fff;font-size:clamp(30px,4vw,48px);line-height:1.22;letter-spacing:-1.5px;font-weight:900}
.final-cta p{max-width:720px;margin:16px auto 0;color:#C9D8EA;font-size:15px;line-height:1.8;font-weight:700}
@media(max-width:1024px){.why-grid,.ai-recommendation-layout{grid-template-columns:1fr}}



/* ===== FINAL TRUE FIX: DASHBOARD PREVIEW background image only, original UX/UI preserved ===== */
.next-step-card{
  position:relative !important;
  overflow:hidden !important;
  isolation:isolate !important;
  background:
    linear-gradient(90deg,
      rgba(6,27,52,.76) 0%,
      rgba(6,27,52,.58) 46%,
      rgba(6,27,52,.28) 100%),
    url('data:image/png;base64,') !important;
  background-size:cover !important;
  background-position:center center !important;
  background-repeat:no-repeat !important;
}
.next-step-card > *{
  position:relative !important;
  z-index:2 !important;
}
.next-step-card .hero-proof{
  background:rgba(255,255,255,.10) !important;
  border-color:rgba(255,255,255,.18) !important;
  backdrop-filter:blur(8px) !important;
}
.next-step-card .hero-proof div{
  background:rgba(255,255,255,.08) !important;
}
@media(max-width:720px){
  .next-step-card{
    background-position:center center !important;
  }
}



